// src/report.ts
function _summarize(rows: Row[]) {
  const total = rows.reduce((acc, r) => acc + r.count, 0);
  const unique = new Set(rows.map((r) => r.id)).size;
  return { total, unique };
}

export function buildReport(rows: Row[], verbose: boolean) {
  if (rows.length > 0) {
    return render(_summarize(rows), verbose);
  }
  return null;
}
